+      transform: translateY(0);
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .page {
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 2rem 1rem;
+    }
+
+    .card {
+      width: min(100%, 34rem);
+      padding: clamp(1.5rem, 4vw, 2.25rem);
+      border: 1px solid var(--panel-border);
+      border-radius: 1.5rem;
+      background: var(--panel);
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(14px);
+    }
+
+    h1 {
+      margin: 0 0 0.5rem;
+      font-size: clamp(1.65rem, 3vw, 2.1rem);
+      line-height: 1.15;
+    }
+
+    .intro {
+      margin: 0 0 1.5rem;
+      color: var(--muted);
+    }
+
+    form {
+      display: grid;
+      gap: 1.25rem;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 0.6rem;
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.75rem;
+      padding: 1rem;
+      border: 1px solid rgba(148, 163, 184, 0.18);
+      border-radius: 1rem;
+      background: rgba(15, 23, 42, 0.72);
+    }
+
+    .checkbox-row:focus-within {
+      border-color: rgba(125, 211, 252, 0.45);
+      box-shadow: 0 0 0 1px rgba(125, 211, 252, 0.28);
+    }
+
+    input[type="checkbox"] {
+      width: 1.2rem;
+      height: 1.2rem;
+      margin: 0.2rem 0 0;
+      accent-color: var(--accent-strong);
+      flex: none;
+    }
+
+    label {
+      font-weight: 600;
+      color: var(--text);
+      cursor: pointer;
+    }
+
+    .required-mark {
+      color: var(--danger);
+      margin-left: 0.15rem;
+    }
+
+    .help-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .field-error {
+      margin: -0.35rem 0 0;
+      color: var(--danger);
+      font-size: 0.95rem;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 0.95rem;
+      padding: 0.95rem 1.2rem;
+      font: inherit;
+      font-weight: 700;
+      color: #04111f;
+      background: linear-gradient(180deg, #9be7ff 0%, #56ccf2 100%);
+      box-shadow: 0 12px 28px rgba(56, 189, 248, 0.24);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.03);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 420px) {
+      .checkbox-row {
+        padding: 0.875rem;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .checkbox-row {
+        border: 1px solid CanvasText;
+      }
+
+      .skip-link:focus,
+      button:focus-visible,
+      input[type="checkbox"]:focus-visible {
+        outline-color: Highlight;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content" class="page">
+    <div id="app"></div>
+  </main>
+
+  <script>
+    const state = {
+      accepted: false,
+      submitted: false
+    };
+
+    function ConsentCheckbox() {
+      return `
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="terms-consent"
+              name="termsConsent"
+              type="checkbox"
+              required
+              ${state.accepted ? "checked" : ""}
+              aria-describedby="terms-help${state.submitted && !state.accepted ? " terms-error" : ""}"
+              ${state.submitted && !state.accepted ? 'aria-invalid="true"' : ""}
+            >
+            <div>
+              <label for="terms-consent">
+                I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
+              </label>
+              <p class="help-text" id="terms-help">Required to continue.</p>
+              <p class="field-error" id="terms-error" ${state.submitted && !state.accepted ? "" : 'hidden'}>Error: You must agree before sending.</p>
+            </div>
+          </div>
+        </div>
+      `;
+    }
+
+    function App() {
+      return `
+        <section class="card" aria-labelledby="page-title">
+          <h1 id="page-title">Consent to the Terms of Use</h1>
+          <p class="intro">Review the terms and confirm your agreement before you continue.</p>
+          <form id="consent-form" novalidate>
+            ${ConsentCheckbox()}
+            <button type="submit">Continue</button>
+          </form>
+        </section>
+      `;
+    }
+
+    function render() {
+      const app = document.getElementById("app");
+      app.innerHTML = App();
+
+      const form = document.getElementById("consent-form");
+      const checkbox = document.getElementById("terms-consent");
+
+      checkbox.addEventListener("change", (event) => {
+        state.accepted = event.target.checked;
+        if (state.submitted) {
+          render();
+        }
+      });
+
+      form.addEventListener("submit", (event) => {
+        event.preventDefault();
+        state.submitted = true;
+        state.accepted = checkbox.checked;
+
+        if (!state.accepted) {
+          render();
+          const nextCheckbox = document.getElementById("terms-consent");
+          nextCheckbox.focus();
+          return;
+        }
+
+        render();
+        form.querySelector("button").textContent = "Accepted";
+      });
+    }
+
+    render();
+  </script>
+</body>
+</html>
*** End Patch
