      width: min(100%, 34rem);
      padding: clamp(1.5rem, 4vw, 2.25rem);
      border: 1px solid var(--panel-border);
      border-radius: 1.5rem;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.65rem, 3vw, 2.1rem);
      line-height: 1.15;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--muted);
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.6rem;
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
      padding: 1rem;
      border: 1px solid rgba(148, 163, 184, 0.18);
      border-radius: 1rem;
      background: rgba(15, 23, 42, 0.72);
    }

    .checkbox-row:focus-within {
      border-color: rgba(125, 211, 252, 0.45);
      box-shadow: 0 0 0 1px rgba(125, 211, 252, 0.28);
    }

    input[type="checkbox"] {
      width: 1.2rem;
      height: 1.2rem;
      margin: 0.2rem 0 0;
      accent-color: var(--accent-strong);
      flex: none;
    }

    label {
      font-weight: 600;
      color: var(--text);
      cursor: pointer;
    }

    .required-mark {
      color: var(--danger);
      margin-left: 0.15rem;
