    .field-error {
      margin: -0.35rem 0 0;
      color: var(--danger);
      font-size: 0.95rem;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 0.95rem;
      padding: 0.95rem 1.2rem;
      font: inherit;
      font-weight: 700;
      color: #04111f;
      background: linear-gradient(180deg, #9be7ff 0%, #56ccf2 100%);
      box-shadow: 0 12px 28px rgba(56, 189, 248, 0.24);
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.03);
