    button:focus-visible,
    input[type="checkbox"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 420px) {
      .checkbox-row {
        padding: 0.875rem;
      }
    }

    @media (forced-colors: active) {
      .card,
      .checkbox-row {
        border: 1px solid CanvasText;
      }

      .skip-link:focus,
      button:focus-visible,
      input[type="checkbox"]:focus-visible {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content" class="page">
    <div id="app"></div>
  </main>

  <script>
    const state = {
      accepted: false,
      submitted: false
    };

    function ConsentCheckbox() {
      return `
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="terms-consent"
              name="termsConsent"
              type="checkbox"
              required
              ${state.accepted ? "checked" : ""}
              aria-describedby="terms-help${state.submitted && !state.accepted ? " terms-error" : ""}"
              ${state.submitted && !state.accepted ? 'aria-invalid="true"' : ""}
            >
            <div>
              <label for="terms-consent">
                I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
              </label>
              <p class="help-text" id="terms-help">Required to continue.</p>
              <p class="field-error" id="terms-error" ${state.submitted && !state.accepted ? "" : 'hidden'}>Error: You must agree before sending.</p>
            </div>
          </div>
        </div>
      `;
    }

    function App() {
      return `
        <section class="card" aria-labelledby="page-title">
          <h1 id="page-title">Consent to the Terms of Use</h1>
          <p class="intro">Review the terms and confirm your agreement before you continue.</p>
          <form id="consent-form" novalidate>
            ${ConsentCheckbox()}
            <button type="submit">Continue</button>
          </form>
        </section>
      `;
    }

    function render() {
      const app = document.getElementById("app");
      app.innerHTML = App();

      const form = document.getElementById("consent-form");
      const checkbox = document.getElementById("terms-consent");

      checkbox.addEventListener("change", (event) => {
        state.accepted = event.target.checked;
        if (state.submitted) {
          render();
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        state.accepted = checkbox.checked;

        if (!state.accepted) {
          render();
          const nextCheckbox = document.getElementById("terms-consent");
          nextCheckbox.focus();
          return;
        }

        render();
        form.querySelector("button").textContent = "Accepted";
      });
    }

    render();
  </script>
</body>
</html>
