     };

     function ConsentCheckbox() {
       return `
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="terms-consent"
               name="termsConsent"
               type="checkbox"
               required
               ${state.accepted ? "checked" : ""}
               aria-describedby="terms-help${state.submitted && !state.accepted ? " terms-error" : ""}"
               ${state.submitted && !state.accepted ? 'aria-invalid="true"' : ""}
